    ('R01', 'R01.01', 'Superestimação da demanda imobiliária', ARRAY['Pesquisa de mercado baseada só em anúncios, sem dados de vendas efetivas da região', 'Extrapolação de ciclo de alta recente sem considerar juros e renda das famílias', 'Público-alvo definido sem checar renda compatível com o crédito disponível', 'Intenção de compra de eventos de lançamento tratada como demanda firme']::TEXT[], ARRAY['Estoque de unidades sem venda após a conclusão da obra', 'Receita de vendas abaixo do fluxo usado na aprovação do investimento', 'Necessidade de aporte adicional dos sócios para concluir a obra', 'Dificuldade de atingir a demanda mínima exigida pelo banco financiador']::TEXT[], ARRAY['Estudo de mercado contratado com dados de absorção da região, arquivado no GED do empreendimento', 'Cenário pessimista de demanda simulado no estudo de viabilidade e aprovado pela diretoria em ata', 'Pré-lançamento com meta mínima de reservas registrada antes da decisão de iniciar a obra', 'Validação da faixa de renda do público com simulação de crédito em bancos parceiros documentada']::TEXT[], ARRAY['Revisar tabela de preços e condições de pagamento com aprovação formal da diretoria', 'Reprogramar o ritmo da obra por etapas para reduzir exposição de caixa', 'Avaliar conversão de parte do estoque para locação com estudo de rentabilidade']::TEXT[], ARRAY['Reservas e propostas abaixo da meta mensal no funil comercial', 'Taxa de conversão de visitas em propostas caindo por três meses seguidos', 'Unidades disponíveis no espelho de vendas acima do previsto para a etapa da obra']::TEXT[], ARRAY['financeira', 'prazo', 'reputacional']::TEXT[], ARRAY['viabilidade', 'aquisicao', 'projeto_aprovacao']::TEXT[], ARRAY['residencial', 'comercial', 'galpao_industrial', 'loteamento']::TEXT[], ARRAY['venda_na_planta', 'financiamento_bancario']::TEXT[], ARRAY['comercial', 'imovib', 'investidor', 'financeiro']::TEXT[], '{}'::TEXT[], false, NULL, 'rascunho'),
    ('R01', 'R01.02', 'Precificação de venda ou locação incompatível com o mercado', ARRAY['Preço definido a partir do custo mais margem, sem comparação com imóveis concorrentes', 'Amostra de comparáveis com padrão, idade ou localização diferentes do produto', 'Valor de aluguel estimado sem considerar vacância e carência usuais da região', 'Tabela não atualizada após mudança relevante de juros ou do custo da obra']::TEXT[], ARRAY['Preço alto trava as vendas e obriga descontos não previstos', 'Preço baixo esgota as unidades e reduz a margem do empreendimento', 'Avaliação bancária abaixo do preço de venda reprova financiamentos de compradores', 'Contratos de locação assinados abaixo do valor de mercado por longo prazo']::TEXT[], ARRAY['Laudo de avaliação com comparáveis de mercado elaborado conforme norma e arquivado no GED', 'Tabela de preços por unidade aprovada pela diretoria com registro de versão e data', 'Revisão trimestral da tabela comparando preço praticado com avaliação bancária das unidades', 'Estudo de aluguel de mercado com vacância e carência usado na viabilidade de locação']::TEXT[], ARRAY['Reajustar tabela por tipologia de unidade com base nas propostas perdidas por preço', 'Oferecer condições de pagamento em vez de desconto direto, com aprovação de alçada']::TEXT[], ARRAY['Propostas perdidas por preço registradas no funil comercial acima de um terço do total', 'Avaliação bancária das unidades abaixo do preço de tabela em contratos de financiamento', 'Desconto médio concedido nas vendas crescente em relação à tabela aprovada']::TEXT[], ARRAY['financeira', 'reputacional']::TEXT[], ARRAY['viabilidade', 'projeto_aprovacao', 'entrega', 'pos_obra']::TEXT[], ARRAY['residencial', 'comercial', 'galpao_industrial', 'loteamento']::TEXT[], ARRAY['venda_na_planta', 'locacao', 'financiamento_bancario']::TEXT[], ARRAY['comercial', 'locacoes', 'imovib']::TEXT[], ARRAY['ABNT NBR 14653 – avaliação de bens']::TEXT[], false, NULL, 'rascunho'),
